// IMAGE: draws after the buffers each frame. It reads the ink from [iBuffer1] and shades it, with a
// glossy sheen where the ink is thick. The water itself ([iBuffer0]) is invisible.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 size = iResolution.xy;
  vec2 uv = fragCoord / size;
  vec2 px = 1.5 * iResolution.y / 400. / size;
  vec3 ink = texture(iBuffer1, uv).rgb;
  float thickness = dot(ink, vec3(0.33));
  vec2 slope = vec2(
    dot(texture(iBuffer1, uv + vec2(px.x, 0.)).rgb - texture(iBuffer1, uv - vec2(px.x, 0.)).rgb, vec3(0.33)),
    dot(texture(iBuffer1, uv + vec2(0., px.y)).rgb - texture(iBuffer1, uv - vec2(0., px.y)).rgb, vec3(0.33)));
  vec3 normal = normalize(vec3(-4. * slope, 1.));
  float shine = pow(max(dot(reflect(normalize(vec3(0.4, -0.6, -1.)), normal), vec3(0., 0., 1.)), 0.), 20.);
  vec3 col = vec3(0.02, 0.02, 0.04) + (1. - exp(-2. * ink)) + 0.8 * shine * min(thickness, 1.);
  fragColor = vec4(col, 1.);
}

