// SHARED: everything defined here can be used in every tab. [iBuffer0] and [iBuffer1] both use these
// to find the jets. Two jets circle the middle, facing inwards, and spray water and ink. The
// [Timeline] sets how hard they spray and how far round they've gone.
#define strength iFloat0
#define turn iFloat1

vec2 jetPosition(int i) {
  float angle = turn + 3.1416 * float(i);
  return 0.5 * iResolution.xy + 0.3 * iResolution.y * vec2(cos(angle), sin(angle));
}

vec2 jetDirection(int i) {
  // Mostly towards the middle, a little to one side, so the streams swirl round each other.
  float angle = turn + 3.1416 * float(i) + 3.1416 + 0.35;
  return vec2(cos(angle), sin(angle));
}

float nearJet(int i, vec2 fragCoord) {
  vec2 d = (fragCoord - jetPosition(i)) / (0.015 * iResolution.y);
  return exp(-dot(d, d));
}

// Each jet's ink colour, drifting round the colour wheel as it plays.
vec3 jetColour(int i) {
  return 0.5 + 0.5 * cos(6.2832 * (0.04 * iTime + 0.45 * float(i) + vec3(0., 0.33, 0.67)));
}

