// iBuffer0: THE WATER. Each pixel holds the water's velocity there (x and y, in pixels a
// frame), its pressure (z) and how fast it's spinning (w). It reads its own last frame, moves the
// water along, and lets the jets push it (see the [shared.glsl] tab). [iBuffer1] reads this to carry the ink.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  if (iFrame == 0) {
    fragColor = vec4(0.);
    return;
  }
  vec2 size = iResolution.xy;
  float cell = iResolution.y / 400.;  // So it flows the same at any size.
  vec4 here = texture(iBuffer0, fragCoord / size);
  // The water carries itself along: take the velocity from where this water was a frame ago.
  vec4 moved = texture(iBuffer0, (fragCoord - here.xy) / size);
  vec4 left = texture(iBuffer0, (fragCoord - vec2(cell, 0.)) / size);
  vec4 right = texture(iBuffer0, (fragCoord + vec2(cell, 0.)) / size);
  vec4 down = texture(iBuffer0, (fragCoord - vec2(0., cell)) / size);
  vec4 up = texture(iBuffer0, (fragCoord + vec2(0., cell)) / size);
  // Water can't bunch up: pressure builds where it flows in, and pushes it back out.
  float inflow = -0.5 * (right.x - left.x + up.y - down.y) / cell;
  float pressure = 0.25 * (left.z + right.z + down.z + up.z) + 0.25 * cell * cell * inflow;
  // A little viscosity smooths out the smallest ripples.
  vec2 nearby = 0.25 * (left.xy + right.xy + down.xy + up.xy);
  vec2 velocity = mix(moved.xy, nearby, 0.1) - 0.5 * vec2(right.z - left.z, up.z - down.z) / cell;
  // Keep the swirls swirling: push sideways, away from where the neighbours spin faster. The push
  // fades out where the spin barely changes, so it doesn't stir up noise.
  float spin = 0.5 * (right.y - left.y - up.x + down.x) / cell;
  vec2 towardsSpin = vec2(abs(right.w) - abs(left.w), abs(up.w) - abs(down.w));
  towardsSpin /= length(towardsSpin) + 0.05;
  velocity += 0.5 * cell * spin * vec2(towardsSpin.y, -towardsSpin.x);
  for (int i = 0; i < 2; i++) {
    velocity += 0.8 * cell * strength * nearJet(i, fragCoord) * jetDirection(i);
  }
  velocity *= 0.996;
  float speed = length(velocity);
  if (speed > 6. * cell) {
    velocity *= 6. * cell / speed;
  }
  fragColor = vec4(velocity, pressure, spin);
}

// iBuffer1: THE INK. Each pixel holds how much of each colour of ink is there. It reads its own
// last frame and the water's velocity from [iBuffer0], carries the ink along with the water, and
// adds fresh ink at the jets (see the [shared.glsl] tab). The [Image.glsl] tab draws it.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  if (iFrame == 0) {
    fragColor = vec4(0.);
    return;
  }
  vec2 size = iResolution.xy;
  vec2 velocity = texture(iBuffer0, fragCoord / size).xy;
  vec3 ink = texture(iBuffer1, (fragCoord - velocity) / size).rgb * 0.997;
  for (int i = 0; i < 2; i++) {
    ink += 0.25 * strength * nearJet(i, fragCoord) * jetColour(i);
  }
  fragColor = vec4(min(ink, vec3(3.)), 1.);
}
